function legacyInAppLinksGuidance(visibility = {}, options2 = {}) {
  const concise = options2.concise === true;
  const taught = legacyTaughtSettingsAnchorIds(visibility);
  const tabs = taughtOverviewTabIds(visibility);
  const guidanceByRoute = concise ? conciseRouteGuidance(taught, tabs) : routeGuidance(taught, tabs);
  return [
    concise ? CONCISE_LEAD : LEAD2,
    ...LEADING_ROUTES.map((route) => guidanceByRoute[route]),
    concise ? CONCISE_TAIL : TAIL,
    ...TRAILING_ROUTES.map((route) => guidanceByRoute[route])
  ].filter((line) => line.length > 0).join(" ");
}

