  annotations: {
    "settings.openers": ["There is no gear icon in the chat and no macOS Preferences menu item."],
    "sidebar.roster": [
      "Team Bots sit inline in the roster with a team mark; there is no separate Team Bots region."
    ],
    "sidebar.botActions.Delete": [
      "Delete is not in Settings. There is no archive; hiding keeps the Bot and its chat."
    ],
    "sidebar.targets": [
      "Tasks are listed on the Details view of the Bot details pane in both layouts; only Tasks with a webhook trigger show these fields."
    ],
    "settings.row.update-computer": [
      "It moves the box to a fresh instance while keeping files and logins, so installed software (apt/npm/pip packages, CLIs, docker images) must be reinstalled."
    ],
    "settings.row.reset-computer": [
      "It restores from the last saved snapshot and can lose recent unsynced work, so steer users to Update first.",
      "A reset never touches memory that lives off the computer; memory kept on the computer is inside the snapshot it restores."
    ],
    "infoPane.simplified.bot": [
      "The Bot's label (its one-line title) sits under the name on accounts that show it and is edited in place like the name. There is no instructions or description text field in this layout for a personal Bot; it changes how it behaves when told in chat."
    ],
    "settings.row.update-channel": [
      "Most accounts have only the Stable track and never see this row, so do not send a user to it unless they already see it."
    ],
    "chat.messages": [
      "A sent message can be reacted to, replied to, copied, and have its attachments downloaded, and a link to it can be copied; a message that renders a page can be opened as one. There is no delete, edit, archive, or pin for a sent message; only a message that failed to send can be deleted."
    ],
    plugins: [
      "Plugins (connectors, MCP servers, and the app's own plugins) are managed on the Plugins page, not in Settings; there is no Plugins tab in Settings.",
      "Each plugin opens its own detail page from the Plugins page; connecting, reconnecting, and removing happen there."
    ],
    "plugins.native.email": [
      "A Bot's email address is claimed here, on the Email plugin's page; it is not a Settings row."
    ],
    "plugins.native.onepassword": [
      'Connected 1Password accounts are listed on this page. A vault connected with a token shows "Refresh vault" and "Remove" (plus "Update" while its access is expiring or has lapsed); an account signed in through 1Password shows "Disconnect" (plus "Reconnect" once the connection lapses). Disconnecting 1Password happens here.'
    ],
    teamBots: [
      "A Bot is shared with a team from the Share action in the Details pane header, which asks the Bot to make a Team Bot copy; it is offered for a Bot other than the main Bot.",
      '"Create a copy", in the same Share menu, shares a template link and does not need a team.'
    ],
    mobile: [
      "The phone app lays its Settings and Bot details out differently and has no local computer of its own.",
      "Settings, plugin, bot-template and agent links (grokbot://app/v1/settings, /plugin/add, /bot-template, /agent) open on the phone too, a settings link on the screen its row's phone marking names, so those links are paths that work on both apps; desktop-only routes (the sidebar account name, the Cmd+, shortcut, context menus) are not.",
      "Sidebar links (grokbot://app/v1/sidebar) are desktop-only: the phone has no Bot details pane; its stand-in is the Bot profile described below.",
      "For anything else, give phone users the outcome and say which steps need the desktop app."
    ]
  }
