// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/hosts/noDesktop+noUserComputer/tools/Shell/description.md
var description_default5 = "Executes a given command in a shell session with optional foreground timeout.\n\nUse it for commands, scripts, installs, and creating or converting files. Read files with Read rather than `cat`, `head`, or `tail`, search file contents with `rg` rather than `grep` or `find`, and wait for a background command with AwaitShell rather than `sleep`. Before a destructive git step (force-pushing, skipping hooks with `--no-verify`, amending or rebasing commits that are already pushed, `reset --hard`), tell the user what it would overwrite and get their confirmation first, even when they asked for it.\n\n- Do not truncate output with `head`, `tail`, or `sed -n` solely to limit its size; large output is saved to a terminal file.\n- Run independent commands as parallel Shell calls. Chain dependent commands with `&&`.\n";

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/hosts/noDesktop+noUserComputer/tools/Shell/schema.json
var schema_default5 = '{\n  "properties": {\n    "block_until_ms": {\n      "description": "How long to block and wait for the command to complete before moving it to background (in milliseconds). Defaults to 30000ms (30 seconds). Set to 0 to immediately run the command in the background. The timer includes the shell startup time.",\n      "type": "number"\n    },\n    "command": {\n      "description": "The command to execute",\n      "type": "string"\n    },\n    "description": {\n      "description": "Very short phrase naming what this command does; shown to the user after the word \\"Ran\\". Avoid leading with verbs or using trailing periods",\n      "type": "string"\n    },\n    "working_directory": {\n      "description": "The absolute path to the working directory to execute the command in (defaults to current directory)",\n      "type": "string"\n    }\n  },\n  "required": [\n    "command"\n  ],\n  "type": "object"\n}\n';

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/hosts/noDesktop+noUserComputer/tools/Task/description.md
var description_default6 = "Start a subagent: a separate agent that works on one task and reports back to you.\n- It cannot see this conversation or the user. Its prompt must be self-contained: the goal, the context and exact values it needs, and what to report back.\n- To follow up with an agent that finished, pass its ID as resume; it keeps its context. Without resume, each call starts fresh.\n- Its final message comes back to you, not the user. Trust it.\n\nAvailable subagent_types and a quick description of what they do:\n- executor: Your workhorse: a background subagent with your full work toolset (Shell, box tools, web, MCP tools, CloudAgent) that executes one stream of work while you stay available to the user. Reuse or resume an idle executor for new work in the same workstream. Typically you'll use one or two active executors; four is a soft maximum unless the user is explicitly multitasking or requests parallel threads. It starts with no context. The dispatch prompt must be self-contained: the goal, the specifics, relevant conversation context, any of your memories or user preferences that matter, explicit success criteria, and what to report back. It runs in the background like any Task: you are notified when it finishes, so do not poll or await it. It runs headless and cannot talk to the user; it reports its result back to you, and you deliver it.\n- videoReview: Analyze videos with an expert visual video model. Pass file paths via the `file_attachments` parameter. Use this to verify your understanding of a video you generated before referencing it in your response. Your prompt should include: (1) what you believe is in the video, (2) questions to verify.\n- watchVideo: Describe or analyze videos with an expert video description and analysis model. Use WatchVideo for user-inputted videos; if you generate a video artifact, prefer VideoReview. Use this subagent type to generate a description of user-provided videos, or to ask specific questions about said videos. Pass file paths via the `file_attachments` parameter. ALWAYS start by asking for a video description by asking \"Describe what is happening in the attached video, in detail\". You may resume the same subagent to ask more specific, detailed follow-up questions. When using, include relevant context about the video, e.g. details from the conversation about what the video may contain and why it is relevant (do not make assumptions, just share what you know). When resuming, you need not re-attach the videos.\n\nWhen an agent runs in the background, you will be automatically notified when it completes after you end your own turn - do NOT AwaitShell or poll it. Continue with other work or end your turn instead. Don't mention this to the user.\n";

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/hosts/noDesktop+noUserComputer/tools/Task/schema.json
var schema_default6 = `{
  "properties": {
    "description": {
      "description": "A short, user-friendly title for the subagent. This appears in the UI as the subagent's name. Make it concrete and distinct, consider recent titles to avoid reuse. For resumed subagents which you are prompting to work on a separate task, give an updated description based on the latest work the subagent is performing. (Do not rename if the subagent is continuing work on the same high-level task.)",
      "type": "string"
    },
    "file_attachments": {
      "description": "Optional array of file paths to images or videos to attach to the subagent. Files are read and attached to the subagent's context. Use to forward relevant media to any subagent (e.g. pass a user-attached image's saved file path so the subagent sees the actual image rather than a prose description).",
      "items": {
        "type": "string"
      },
      "type": "array"
    },
    "prompt": {
      "description": "The task for the agent to perform",
      "type": "string"
    },
    "resume": {
      "description": "Optional agent ID to resume from. If provided, sends a follow-up message to the agent after it has completed. Requests to a currently running asynchronous agent fail; wait for completion before resuming.",
      "type": "string"
    },
    "run_in_background": {
      "description": "Run the agent in the background (returns output_file path to check later). If this is false, you will be blocked until the agent completes. When true, the background subagent will send a notification when it completes.",
      "type": "boolean"
    },
    "subagent_type": {
      "description": "Subagent type to use for this task. Must be one of: executor, videoReview, watchVideo.",
      "enum": [
        "executor",
        "videoReview",
        "watchVideo"
      ],
      "type": "string"
    }
  },
  "required": [
    "description",
    "prompt",
    "subagent_type"
  ],
  "type": "object"
}
`;

