// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/GenerateImage/description.md
var description_default21 = 'Generate an image file from a text description.\n\nSTRICT INVOCATION RULES (must follow):\n- Only use this tool when the user explicitly asks for an image. Do not generate images "just to be helpful".\n- Do not use this tool for data heavy visualizations such as charts, plots, tables.\n\nGeneral guidelines:\n- Provide a concrete description first: subject(s), layout, style, colors, text (if any), and constraints.\n- If the user requests an aspect ratio, set `aspect_ratio` to one of "1:1", "4:3", "3:4", "16:9", or "9:16".\n- If the user provides reference images, include them in `reference_image_paths`.\n- The generated image is saved to disk and is not shown to the user automatically; attach its returned `file://` URL with SendToUser (`images` on a `type: "text"` message, or `type: "attachment"` with `url`) to show it to the user.\n\nExamples that should call this tool:\n- user: "Generate an app icon for a note-taking app, minimal flat vector style." (explicitly requests an image asset)\n- user: "Make a UI mockup of a settings screen with a dark mode toggle." (explicitly requests a UI mockup)\n- user: "Generate an asset of a game character with a sword." (explicitly requests a visual asset)\n\nExamples that should not call this tool:\n- user: "Create a plan to refactor this module." (planning request; respond in text or mermaid diagram)\n- user: "Generate a chart of sales and revenue using data.csv." (data visualization; generate via code)\n\n';

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/GenerateImage/schema.json
var schema_default21 = `{
  "properties": {
    "aspect_ratio": {
      "description": "Optional aspect ratio for the generated image. Supported values are \\"1:1\\", \\"4:3\\", \\"3:4\\", \\"16:9\\", and \\"9:16\\".",
      "enum": [
        "1:1",
        "4:3",
        "3:4",
        "16:9",
        "9:16"
      ],
      "type": "string"
    },
    "description": {
      "description": "A detailed description of the image.",
      "type": "string"
    },
    "filename": {
      "description": "Optional filename for the generated image (e.g., 'diagram.png'). Do not include a directory path - the tool automatically handles where to save and how to display the image. If not provided, a timestamped filename will be generated.",
      "type": "string"
    },
    "reference_image_paths": {
      "description": "Optional array of file paths to reference images as additional inputs.",
      "items": {
        "type": "string"
      },
      "type": "array"
    }
  },
  "required": [
    "description"
  ],
  "type": "object"
}
`;

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/GetDynamicTools/description.md
var description_default22 = `Discover and inspect tools available through dynamic namespaces, e.g. MCP servers.

1. {"namespace":"<id>"}: returns full input schemas and full descriptions for every tool in that namespace.
2. {"namespace":"<id>","toolName":"<name>"}: returns the full schema and full description for one tool.
3. {"pattern":"<regex>"}: searches namespace and tool names across all namespaces using RE2 syntax.
4. {"namespace":"<id>","pattern":"<regex>"}: searches tool names within that namespace.
5. No arguments: returns the full catalog. Prefer a namespace or pattern when possible.

Pattern-search and catalog results shorten long descriptions to 200 characters, ending with "... [truncated]". Namespace and single-tool lookups always return the complete description, so fetch the tool directly when you need the full text.
The response includes namespaceStatus for MCP-backed namespaces; do not treat namespaces in "needsAuth", "needsGrant", "error", or "loading" states as usable.
Always call this tool to discover a tool's schema before calling it with CallDynamicTool.

MCP authentication: a namespace whose namespaceStatus is "needsAuth" or "needsGrant" stays unusable until the user connects it or grants you access. Call AuthenticateMcpServer on it instead of refetching this descriptor; it is already installed, so never propose installing it.
`;

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/GetDynamicTools/schema.json
var schema_default22 = '{\n  "properties": {\n    "namespace": {\n      "description": "Dynamic namespace to inspect, e.g. an MCP server.",\n      "type": "string"\n    },\n    "pattern": {\n      "description": "RE2 regex pattern to search namespace and tool names (max 256 chars). Optionally combine with namespace to scope the search.",\n      "type": "string"\n    },\n    "toolName": {\n      "description": "Tool name within the namespace. Requires namespace to be set.",\n      "type": "string"\n    }\n  },\n  "type": "object"\n}\n';

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/GetMcpServerStatus/description.md
var description_default23 = "The runtime status of the user's installed MCP servers (connected / needsAuth / needsGrant / error, per account). needsGrant means the user already connected it but has not granted it this turn: call AuthenticateMcpServer for it and nothing else; never treat it as missing, never install anything, and never open the browser for the same service. Pass server_id (the server identifier, NEVER a display name) for one server; omit it to list everything. This is the complete list: it also shows connectors waiting on sign-in or a grant, which GetDynamicTools can leave out, so check it before treating a service as having no connector. Use it too for per-account detail, custom instructions, or to check a connector after installing or authenticating. To use a connector GetDynamicTools already lists, GetDynamicTools is enough. A server that is slow to answer reads initializing; check it again shortly. Read-only and never needs the user's permission.\n";

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/GetMcpServerStatus/schema.json
var schema_default23 = '{\n  "properties": {\n    "server_id": {\n      "description": "Optional. One server to report on. The server identifier shown by GetMcpServerStatus. It is the same identifier that GetDynamicTools and CallDynamicTool address, e.g. \\"dashboard-team-1-Slack\\". Never a display name. Omit to list every installed server.",\n      "type": "string"\n    }\n  },\n  "type": "object"\n}\n';

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/GetPlugin/description.md
var description_default24 = "Full detail for one plugin by its STABLE plugin id (from SearchPlugins): what it includes (connectors, skills), its install state, any setup fields InstallPlugin needs (with required/secret flags), and the installed MCP servers backing it. Read this before installing a plugin with setup fields, and before uninstalling (to know the full scope you must disclose). Using a connector GetDynamicTools already lists does not need it. Read-only.\n";

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/GetPlugin/schema.json
var schema_default24 = '{\n  "properties": {\n    "plugin_id": {\n      "description": "The stable plugin id from SearchPlugins.",\n      "minLength": 1,\n      "type": "string"\n    }\n  },\n  "required": [\n    "plugin_id"\n  ],\n  "type": "object"\n}\n';

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/InstallPlugin/description.md
var description_default25 = "Install a plugin by its STABLE plugin id (from SearchPlugins) into the user's Cursor account. Only call this after the user has agreed. Confirm with a question widget first, since installing changes the user's configuration. Idempotent: re-installing an installed plugin is safe. Pass any setup values GetPlugin lists (ask the user for secrets like API keys, never guess). If an installed connector needs authentication, its connect card is shown to the user automatically. Finish unrelated work, then end your turn; you're resumed when they authorize. New tools and skills become available on your next message.\n";

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/InstallPlugin/schema.json
var schema_default25 = `{
  "properties": {
    "plugin_id": {
      "description": "The stable plugin id from SearchPlugins.",
      "minLength": 1,
      "type": "string"
    },
    "values": {
      "description": "Optional setup values keyed by the plugin's field key from GetPlugin (e.g. { \\"CONTEXT7_API_KEY\\": \\"...\\" }). Provide every required field. Ask the user for any secret you don't already have.",
      "type": "object"
    }
  },
  "required": [
    "plugin_id"
  ],
  "type": "object"
}
`;

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/ListMachines/description.md
var description_default26 = `List the user's registered machines with their machineId, label, kind (desktop, ios, or android), and current local-exec connection status. Pass a desktop's machineId to Shell, Read, or AwaitShell to use that machine instead of the box, or to CopyToBox and CopyFromBox for file transfers; a phone never takes those tools. Only a connected phone lists mobileLocalTools, each on-device tool with its state: ready, needs_permission (the phone can still ask for the OS permission), denied (only the phone's Settings app can grant it), or unavailable. A call to a tool still missing its permission posts a permission card in the chat for the user to tap; a phone without mobileLocalTools offers none right now. Messages the user sends from their desktop app carry a "[Sent from machine <machineId>]" note naming the machine they are on; when they don't say which machine to use, default to the one their latest message was sent from.
`;

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/ListMachines/schema.json
var schema_default26 = '{\n  "properties": {},\n  "type": "object"\n}\n';

