// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/Read/description.md
var description_default30 = "Reads a file on your own computer (the box), the same filesystem Shell and CopyToBox act on. This is your default surface, including your own files under /home/box.\n\nText files include line numbers and support offset/limit paging. Image files (jpeg/jpg, png, gif, webp) are returned inline so you can see them. PDF files are converted to text.\n\nOmit machineId to read from your box. To read from one of the user's computers instead, call ListMachines and pass its machineId. A machine-targeted read uses that computer's filesystem and requires the user's local-tool approval.\n";

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/Read/schema.json
var schema_default30 = '{\n  "properties": {\n    "limit": {\n      "description": "The number of lines to read. Only provide if the file is too large to read at once.",\n      "type": "integer"\n    },\n    "machineId": {\n      "description": "Registered machine identifier.",\n      "type": "string"\n    },\n    "offset": {\n      "description": "The line number to start reading from. Positive values are 1-indexed from the start of the file. Negative values count backwards from the end (e.g. -1 is the last line). Only provide if the file is too large to read at once.",\n      "type": "integer"\n    },\n    "path": {\n      "description": "The absolute path of the file to read.",\n      "type": "string"\n    }\n  },\n  "required": [\n    "path"\n  ],\n  "type": "object"\n}\n';

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/RecallMemory/description.md
var description_default31 = "Search your durable memory for facts that are not in the memory section of your prompt: older log entries, notes that have aged out of the recent slice, and shared user facts recorded by any of this user's assistants.\nRead-only. Results list each fact with its date, tier (profile | log) and, for shared facts, which assistant learned it.\nTo add or drop a fact use UpdateMemory. Prefer this tool over grepping memory folders.\n";

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/RecallMemory/schema.json
var schema_default31 = '{\n  "properties": {\n    "limit": {\n      "description": "Maximum facts to return (default 20, max 50).",\n      "maximum": 50,\n      "minimum": 1,\n      "type": "integer"\n    },\n    "query": {\n      "description": "What to look for. Facts sharing distinctive words with the query rank first; when nothing overlaps (short identifiers like a ticket id or an acronym) a literal case-insensitive substring match is used instead.",\n      "minLength": 1,\n      "type": "string"\n    },\n    "scope": {\n      "description": "Which memory to search: \\"agent\\" is your own memory, \\"user\\" is the shared user memory every assistant of this user contributes to, \\"all\\" (default) is both.",\n      "enum": [\n        "agent",\n        "user",\n        "all"\n      ],\n      "type": "string"\n    }\n  },\n  "required": [\n    "query"\n  ],\n  "type": "object"\n}\n';

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/RestartMcpServers/description.md
var description_default32 = "Restart (reconnect) the installed MCP servers. This is useful when a server is stuck, errored, or you just finished authenticating one. Confirm with the user first if a server is mid-task.\n";

