var description_default33 = "Capture the current box desktop screen without interacting with it. This tool is read-only. To click, type, scroll, wait, or otherwise drive the desktop, delegate the task to a computerUse subagent. The screenshot is saved to disk; attach that file:// path with SendToUser to show the user.\n";

