var schema_default33 = '{\n  "description": "No arguments. Captures the current box desktop screen.",\n  "properties": {},\n  "type": "object"\n}\n';

// raw-text:/workdir/packages/grok-bot-harness/frozen-prompts/grok-bot-2026-10-09/tools/SearchPlugins/description.md
var description_default34 = "Search the plugins the user could install (or already has): marketplace plugins bundling connectors and skills. Say what you're looking for in natural language and results come back ranked by relevance, each with its STABLE plugin id, install state, and what it includes. Use this to discover a capability (Linear, Notion, writing Word documents, \u2026) that GetDynamicTools does not already list, or to check whether a plugin is installed. Using a connector GetDynamicTools already lists needs no search: it has the connector's identifier, status, and tools. Inspect one result with GetPlugin. This is read-only and never needs the user's permission.\n";

